export const ARCHITECTURE_MAP_REL = 'docs/architecture-map.html'
export const ARCHITECTURE_MAP_OPT_OUT_DECISION = 'no-architecture-html'
export const NO_ARCHITECTURE_HTML_DECISION = ARCHITECTURE_MAP_OPT_OUT_DECISION

function resolveOutRel(outRel) {
  const norm = posixPath(String(outRel || ARCHITECTURE_MAP_REL).trim()).replace(/^\.\//, '')
  return norm || ARCHITECTURE_MAP_REL
}

export function isArchitectureMapOptedOut(repoRoot) {
  const root = resolve(repoRoot)
  const agentsText = readTextSafe(join(root, 'AGENTS.md'))
  if (!agentsText) return false
  return readDecisions(agentsText).has(ARCHITECTURE_MAP_OPT_OUT_DECISION)
}

function getHomeMarkers() {
  const raw = String(homedir() || '').trim()
  if (!raw || raw.length < 4) return []
  const fwd = raw.replace(/\\/g, '/').replace(/\/+$/, '')
  const bwd = raw.replace(/\//g, '\\').replace(/\\+$/, '')
  return [...new Set([fwd, bwd].filter((s) => s.length >= 4))]
}

export function containsHomedirLeak(text) {
  const body = String(text || '')
  if (!body) return false
  for (const marker of getHomeMarkers()) {
    if (body.includes(marker)) return true
  }
  return false
}

const DIRTY_DIFF_CLASS_RE = /\bpf-diff-(?:added|modified|removed|impacted)\b/
const DIRTY_DIFF_ATTR_RE = /\bdata-diff-state\s*=\s*["'](?:added|modified|removed|impacted)["']/i
const VISUAL_DATA_SCRIPT_RE = /<script\b[^>]*\bid=["']pf-visual-data["'][^>]*>([\s\S]*?)<\/script>/i

/**
 * 校验常青 `docs/architecture-map.html` 是否残留临时 diff 脏态（两层校验，免疫 `<style>` 静态 CSS 声明）：
 * 1. 解析 `pf-visual-data` JSON，阻断 `hasActiveDiff === true` 或任意非 `context` 的 `diffState` 节点；
 * 2. 剥离全部 `<style>` 与 `<script>` 块后扫描 DOM 是否残留 `pf-diff-*` 或 `data-diff-state` 脏态。
 */
export function detectDirtyDiffOverlay(html) {
  const raw = String(html || '')
  if (!raw) return { dirty: false, detail: null }

  const dataMatch = VISUAL_DATA_SCRIPT_RE.exec(raw)
  if (dataMatch) {
    try {
      const payload = JSON.parse(dataMatch[1])
      if (payload?.hasActiveDiff === true) {
        return { dirty: true, detail: 'pf-visual-data hasActiveDiff=true' }
      }
      const nodeLists = [
        Array.isArray(payload?.tree?.nodes) ? payload.tree.nodes : [],
        Array.isArray(payload?.diagrams?.architecture?.nodes) ? payload.diagrams.architecture.nodes : [],
      ]
      for (const list of nodeLists) {
        const hit = list.find((n) => n?.diffState && n.diffState !== 'context')
        if (hit) {
          return { dirty: true, detail: `pf-visual-data node "${hit.id || 'unknown'}" diffState=${hit.diffState}` }
        }
      }
    } catch { /* ignore unparseable script block; fall through to DOM strip check */ }
  }

  const strippedDom = raw
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
  const classHit = DIRTY_DIFF_CLASS_RE.exec(strippedDom)
  if (classHit) return { dirty: true, detail: `DOM class ${classHit[0]}` }
  const attrHit = DIRTY_DIFF_ATTR_RE.exec(strippedDom)
  if (attrHit) return { dirty: true, detail: `DOM attr ${attrHit[0]}` }

  return { dirty: false, detail: null }
}

function stripHomedirLeaks(text) {
  let out = String(text || '')
  for (const marker of getHomeMarkers()) {
    if (out.includes(marker)) {
      out = out.split(marker).join('~')
    }
  }
  return out
}

function resolveRepoDisplayName(root) {
  const dotGit = join(root, '.git')
  if (existsSync(dotGit)) {
    try {
      if (statSync(dotGit).isFile()) {
        const raw = readTextSafe(dotGit) || ''
        const m = /^gitdir:\s*(.+)$/im.exec(raw)
        if (m) {
          const gitDir = isAbsolute(m[1].trim()) ? resolve(m[1].trim()) : resolve(root, m[1].trim())
          const commonFile = join(gitDir, 'commondir')
          if (existsSync(commonFile)) {
            const cRaw = (readTextSafe(commonFile) || '').trim()
            if (cRaw) {
              const commonDir = isAbsolute(cRaw) ? resolve(cRaw) : resolve(gitDir, cRaw)
              if (basename(commonDir) === '.git') return basename(dirname(commonDir))
            }
          }
        }
      }
    } catch { /* fall back to basename(root) */ }
  }
  return basename(root)
}

export function renderArchitectureMapFromRepo(repoRoot, {
  outRel = ARCHITECTURE_MAP_REL,
  diffOverlay = null,
  changedFiles = null,
  mode = 'architecture-map',
  title = '',
  briefSpec = null,
  analysis = null,
  evidence = null,
  ignoreOptOut = false,
  write = true,
} = {}) {
  const root = resolve(repoRoot)
  const relPath = resolveOutRel(outRel)

  if (!ignoreOptOut && isArchitectureMapOptedOut(root)) {
    return {
      ok: true,
      optedOut: true,
      skipped: true,
      written: false,
      changed: false,
      reason: 'opted-out',
      relPath,
    }
  }

  const fmStatus = readFeatureMapStatus(root)
  if (!fmStatus.exists) {
    return {
      ok: false,
      exitCode: EXIT.FACT,
      reason: 'missing-feature-map',
      message: `${FEATURE_MAP_REL} is missing`,
      relPath,
    }
  }
  if (fmStatus.corrupt || !fmStatus.raw) {
    return {
      ok: false,
      exitCode: EXIT.FACT,
      reason: 'invalid-feature-map',
      message: `${FEATURE_MAP_REL} is not valid JSON`,
      relPath,
    }
  }

  const featureMapSha256 = computeFeatureMapFingerprint(fmStatus.raw)
  const effectiveDiff = diffOverlay || (Array.isArray(changedFiles) ? { changedFiles } : {})
  const hasExplicitName = Boolean(String(fmStatus.raw?.repoName || fmStatus.raw?.project || '').trim())
  const effectiveFeatureMap = hasExplicitName
    ? fmStatus.raw
    : { ...fmStatus.raw, repoName: resolveRepoDisplayName(root) }
  const visualModel = buildVisualModel({
    featureMap: effectiveFeatureMap,
    diffOverlay: effectiveDiff,
    mode,
    title,
    briefSpec,
    analysis,
    evidence,
  })
  visualModel.analysis = analysis || null
  const rendered = renderVisualHtml({
    visualModel,
    featureMapSha256,
    mode,
  })
  const cleanHtml = stripHomedirLeaks(rendered.html)
  const bytes = Buffer.byteLength(cleanHtml, 'utf8')
  const absOut = join(root, relPath)
  const existing = existsSync(absOut) ? readTextSafe(absOut) : ''
  const changed = existing !== cleanHtml

  let written = false
  if (write && changed) {
    writeAtomic(absOut, cleanHtml)
    written = true
  }

  return {
    ok: true,
    optedOut: false,
    skipped: false,
    written,
    changed,
    relPath,
    absPath: absOut,
    bytes,
    featureMapSha256,
    headerLine: rendered.headerLine,
    activeTabs: visualModel.activeTabs || [],
    html: write ? undefined : cleanHtml,
  }
}

/** 单源视觉证据采集原语（异步，供 `architecture-map.html` 与 `verify-tools render` 共用）。 */
export async function collectRepoVisualEvidence({
  workRoot,
  cacheRoot = null,
  featureMap = null,
  telemetrySpans = null,
  useCache = true,
  analysis = null,
  evidence = null,
} = {}) {
  let resolvedAnalysis = analysis || null
  let resolvedEvidence = evidence || null
  if (!workRoot || (resolvedAnalysis && resolvedEvidence)) {
    return { analysis: resolvedAnalysis, evidence: resolvedEvidence }
  }
  try {
    if (!resolvedAnalysis) resolvedAnalysis = await analyzeRepoStatic(workRoot, { useCache, cacheRoot })
    if (!resolvedEvidence) {
      resolvedEvidence = extractMultiDiagramEvidenceSync(workRoot, {
        analysis: resolvedAnalysis,
        featureMap,
        telemetrySpans,
        cacheRoot,
        useCache,
      })
    }
  } catch { /* 静态分析异常时安全降级为功能地图常驻两图 */ }
  return { analysis: resolvedAnalysis, evidence: resolvedEvidence }
}

/** 单源视觉证据采集原语（同步，供 `visual-brief.mjs` 实时投影与 `architecture-map.html` 同源对齐）。 */
