/** 异步全量静态分析 + 3 层 10 类图表证据抽取，渲染干净常青 Studio `docs/architecture-map.html`。 */
export async function renderArchitectureMapAsync(repoRoot, {
  outRel = ARCHITECTURE_MAP_REL,
  telemetrySpans = null,
  ignoreOptOut = false,
  write = true,
  useCache = true,
} = {}) {
  const root = resolve(repoRoot)
  if (!ignoreOptOut && isArchitectureMapOptedOut(root)) {
    return renderArchitectureMapFromRepo(root, { outRel, ignoreOptOut, write })
  }
  const fmStatus = readFeatureMapStatus(root)
  if (!fmStatus.exists || fmStatus.corrupt || !fmStatus.raw) {
    return renderArchitectureMapFromRepo(root, { outRel, ignoreOptOut, write })
  }
  const { analysis, evidence } = await collectRepoVisualEvidence({
    workRoot: root,
    featureMap: fmStatus.raw,
    telemetrySpans,
    useCache,
  })

  return renderArchitectureMapFromRepo(root, {
    outRel,
    analysis,
    evidence,
    ignoreOptOut,
    write,
  })
}

export const syncArchitectureMap = renderArchitectureMapFromRepo

export function verifyArchitectureMapSync(repoRoot, {
  outRel = ARCHITECTURE_MAP_REL,
  featureMapRel = FEATURE_MAP_REL,
  ignoreOptOut = false,
} = {}) {
  const root = resolve(repoRoot)
  const relPath = resolveOutRel(outRel)

  if (!ignoreOptOut && isArchitectureMapOptedOut(root)) {
    return {
      ok: true,
      optedOut: true,
      reason: 'opted-out',
      relPath,
    }
  }

  const fmAbs = join(root, featureMapRel)
  if (!existsSync(fmAbs)) {
    return {
      ok: false,
      code: 'BLOCKED_ARCHITECTURE_MAP_DRIFT',
      exitCode: EXIT.FACT,
      reason: 'missing-feature-map',
      message: `${featureMapRel} does not exist`,
      relPath,
    }
  }

  const headerCheck = verifyArchitectureMapHeader(root, relPath, featureMapRel)
  if (!headerCheck.ok) {
    return {
      ok: false,
      code: 'BLOCKED_ARCHITECTURE_MAP_DRIFT',
      exitCode: EXIT.FACT,
      reason: headerCheck.reason || 'header-mismatch',
      message: `${relPath} is missing or out of sync with ${featureMapRel} (${headerCheck.reason || 'drift'})`,
      expectedSha256: headerCheck.expectedSha || null,
      actualSha256: headerCheck.actualSha || null,
      relPath,
    }
  }

  const html = readTextSafe(join(root, relPath), 4 * 1024 * 1024)
  if (containsHomedirLeak(html)) {
    return {
      ok: false,
      code: 'BLOCKED_ARCHITECTURE_MAP_DRIFT',
      exitCode: EXIT.FACT,
      reason: 'homedir-leak',
      message: `${relPath} contains a machine-specific home directory path`,
      relPath,
    }
  }

  const dirtyCheck = detectDirtyDiffOverlay(html)
  if (dirtyCheck.dirty) {
    return {
      ok: false,
      code: 'BLOCKED_ARCHITECTURE_MAP_DRIFT',
      exitCode: EXIT.FACT,
      reason: 'dirty-diff-overlay',
      message: `${relPath} contains temporary diff overlay state (${dirtyCheck.detail})`,
      relPath,
    }
  }

  return {
    ok: true,
    optedOut: false,
    reason: 'synced',
    relPath,
    expectedSha256: headerCheck.expectedSha,
    actualSha256: headerCheck.actualSha,
  }
}
